package com.example

import com.example.ExamQuestionHelper.QSpec

object DancingLiveExamVannamBank1 {
    private const val T = "උඩරට දහඅට වන්නම්, ශාස්ත්‍රීය කවි හා තාල විග්‍රහය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("උඩරට නර්තන සම්ප්‍රදායේ 'වන්නම' යන වචනය බිඳී ආ මූලික පදයේ අර්ථය කුමක්ද?", "වර්ණනාව හෙවත් යමක ස්වභාවය වර්ණනා කිරීම", "යුද්ධ කිරීම හෙවත් සටන් වැදීම", "නින්දට යාම හෙවත් විවේක ගැනීම", "වේදිකා පසුතල තිර රෙදි සැරසීම", "සංස්කෘත 'වර්ණනා' හෝ දෙමළ 'වණ්ණම්' යන පද ඇසුරෙන් වන්නම බිඳී ආ බව විද්වත්හු දක්වති."),
        q("උඩරට නර්තන සම්ප්‍රදායට අයත් ප්‍රධාන ශාස්ත්‍රීය වන්නම් සංඛ්‍යාව කීයද?", "දහඅටකි (18)", "දොළහකි (12)", "විසිහතරකි (24)", "තිස් දෙකකි (32)", "ගජගා වන්නමේ සිට අසදිස වන්නම දක්වා සම්ප්‍රදායික වන්නම් 18 ක් උඩරට නැටුමේ පවතී."),
        q("දහඅට වන්නම්වලින් පළමුවැන්න වන 'ගජගා වන්නම' මගින් නිරූපණය කරනු ලබන්නේ කුමන සත්වයාගේ ගමන් විලාසයද?", "ඇතාගේ (දළ ඇතාගේ) ගාම්භීර ගමන", "තුරඟාගේ වේගවත් ධාවනය", "මොනරාගේ පිල් විදහා නැටීම", "සිංහයාගේ ගොදුරු සෙවීම", "දළදා මාලිගාවේ ඇතාගේ හෝ ඓරාවණ හස්තියාගේ ගමන ගජගා වන්නමෙන් නිරූපණය කෙරේ."),
        q("වේගයෙන් දිව යන අශ්වයෙකුගේ ගමන් විලාසය හා ජවය වර්ණනා කෙරෙන වන්නම කුමක්ද?", "තුරඟා වන්නම", "ගජගා වන්නම", "උකුසා වන්නම", "මයුරා වන්නම", "සිද්ධාර්ථ කුමරු ගිහිගෙය හැර ගිය කන්ථක අසුගේ ගමන තුරඟා වන්නමට පාදක වී ඇත."),
        q("'මයුරා වන්නම' මගින් වර්ණනා කරනු ලබන පක්ෂියා හා සම්බන්ධ දෙවියා කවුද?", "කතරගම (ස්කන්ධ) දෙවියන්ගේ වාහනය වන මොනරා", "විෂ්ණු දෙවියන්ගේ ගුරුළා", "බ්‍රහ්ම දෙවියන්ගේ හංසයා", "ශිව දෙවියන්ගේ ගොනා", "පිල් විදහා නටන මොනරාගේ ලාලිත්‍යය මයුරා වන්නමෙන් මැනවින් ප්‍රකට කෙරේ."),
        q("'උකුසා වන්නම' මගින් නිරූපණය කරනු ලබන ප්‍රධාන සත්ව චර්යාව කුමක්ද?", "අහසේ සැරිසරමින් ගොදුරු දෙස බලා වේගයෙන් පහත් වීම", "ජලයේ පිහිනා යාම", "ගුහාවක් තුළ නිදා ගැනීම", "බිම දිගේ උරගා යාම", "උකුස්සාගේ පියාසර රටා හා තියුණු බැල්ම උකුසා වන්නමේ නර්තන චලන මගින් පෙන්වයි."),
        q("හාවෙකුගේ හෙවත් මුවෙකුගේ බියගුළු එහෙත් කඩිසර පැනුම් නිරූපණය කරන වන්නම කුමක්ද?", "මුසලඩි වන්නම", "ගජගා වන්නම", "සිංහරාජ වන්නම", "හනුමා වන්නම", "පඳුරු අතරින් පනිමින් වටපිට බලන හාවාගේ ගමන මුසලඩි වන්නමේ කේන්ද්‍රීය තේමාවයි."),
        q("වඳුරෙකුගේ කඩිසර පැනුම් හා උපහාසාත්මක චලන නිරූපණය කෙරෙන උඩරට වන්නම කුමක්ද?", "හනුමා වන්නම", "අසදිස වන්නම", "ගණපති වන්නම", "සුරපති වන්නම", "රාමායණයේ හනුමාන්ගේ චරිතය හා වඳුරන්ගේ චපල ගති සොබා මෙම වන්නමෙන් දැක්වේ."),
        q("සිව්පාවුන්ගේ රජු ලෙස සැලකෙන සිංහයාගේ තේජස හා ගමන නිරූපණය කරන වන්නම කුමක්ද?", "සිංහරාජ වන්නම", "වෛරෝඩි වන්නම", "කිරලා වන්නම", "උරඟා වන්නම", "ගිරි ගුහාවක සිට පිටතට එන සිංහයාගේ ගාම්භීරත්වය හා කේසර සැලීම මෙහි නිරූපණය වේ."),
        q("නාගයෙකුගේ පෙනය පුප්පා ගමන් කරන වක්‍රාකාර විලාසය දැක්වෙන උඩරට වන්නම කුමක්ද?", "නෛයඩි වන්නම", "උදාර වන්නම", "ඊරඩි වන්නම", "කුදිරඩි වන්නම", "සිදුහත් කුමරු දුනු ශිල්ප පෙන්වීම හා නාගයාගේ චලන නෛයඩි වන්නම හා බැඳී ඇත."),
        q("කිරලා නමැති පක්ෂියාගේ ගමන, කෑගැසීම හා පියාසර විලාසය වර්ණනා කරන වන්නම කුමක්ද?", "කිරලා වන්නම", "මයුරා වන්නම", "ගජගා වන්නම", "හනුමා වන්නම", "දිය කඩිති අසල ඇවිදිමින් නාද නඟන කිරලා කුරුල්ලාගේ ගමන මෙම වන්නමට පාදක වේ."),
        q("සර්පයෙකු හෙවත් නාගයෙකු බිම දිගේ ඇදී යන සුමට චලනය පෙන්වන වන්නම කුමක්ද?", "උරඟා වන්නම", "ගණපති වන්නම", "තුරඟා වන්නම", "සිංහරාජ වන්නම", "උරඟුන්ගේ වක්‍ර චලන රටා හා සියුම් අත් චලන උරඟා වන්නමේ විශේෂත්වයකි."),
        q("සදෙව් ලොවට අධිපති ශක්‍ර දේවේන්ද්‍රයාගේ මහිමය වර්ණනා කෙරෙන උඩරට වන්නම කුමක්ද?", "සුරපති වන්නම", "මුසලඩි වන්නම", "කිරලා වන්නම", "උකුසා වන්නම", "උමා දේවිය නැති වූ ශිව දෙවියන් හෝ සුරපති දෙවියන්ගේ කතා පුවත සුරපති වන්නමේ ගැයේ."),
        q("ගණ දෙවියන්ගේ ප්‍රඥාව, රූප ස්වභාවය හා නුවණ වර්ණනා කරමින් ගැයෙන වන්නම කුමක්ද?", "ගණපති වන්නම", "වෛරෝඩි වන්නම", "ඊරඩි වන්නම", "තුරඟා වන්නම", "කලා කටයුතු ආරම්භයේ ආශිර්වාද ගෙනෙන ගණ දෙවි ගුණ ගණපති වන්නමේ වර්ණනා වේ."),
        q("රාජකීය උත්සවයක තේජස හා රජුගේ උදාර ගුණාංග වර්ණනා කරන වන්නම කුමක්ද?", "උදාර වන්නම", "කිරලා වන්නම", "හනුමා වන්නම", "මුසලඩි වන්නම", "සිව්රඟ සෙනඟ සමඟ ගමන් කරන රජුගේ ප්‍රතාපවත් බව උදාර වන්නමෙන් නිරූපණය කෙරේ."),
        q("තෙරුවන් ගුණ හා බුදුරජාණන් වහන්සේගේ අසමසම ගුණ මහිමය වර්ණනා කරන උතුම් වන්නම කුමක්ද?", "අසදිස වන්නම", "වෛරෝඩි වන්නම", "උරඟා වන්නම", "කුදිරඩි වන්නම", "අසදිස වන්නමේ පද රචනය බෞද්ධ සාහිත්‍ය ගෞරවයෙන් පිරිපුන් ශාස්ත්‍රීය කාව්‍යයකි."),
        q("සතුරු බලවේග පරාජය කිරීමේ ඊතල හා යුද ශිල්පය වර්ණනා කෙරෙන වන්නම කුමක්ද?", "ඊරඩි වන්නම", "ගජගා වන්නම", "මයුරා වන්නම", "ගණපති වන්නම", "වේගවත් පහරදීම් හා රණකාමී චලන ඊරඩි වන්නමේ කැපී පෙනේ."),
        q("ඊශ්වර දෙවියන්ගේ හා මැණික් මෙන් බැබළෙන දිව්‍යමය තේජස පිළිබඳව ගැයෙන වන්නම කුමක්ද?", "වෛරෝඩි වන්නම", "මුසලඩි වන්නම", "තුරඟා වන්නම", "කිරලා වන්නම", "වෛරෝඩි වන්නම පංච ශිඛා ආදී දේව පුවත් හා සුරංගනා අලංකාර වර්ණනා කරයි."),
        q("රණ ශූරයෙකුගේ අසුන් පැදීම හා රණබිම දස්කම් හා බැඳුණු වන්නම කුමක්ද?", "ඉරඩි වන්නම හෙවත් කුදිරඩි වන්නම", "අසදිස වන්නම", "මයුරා වන්නම", "සිංහරාජ වන්නම", "වේගවත් පාද චලන හා ජවසම්පන්න රිද්මය මෙම වන්නම්වල දක්නට ලැබේ."),
        q("පැරණි වන්නම් පොත් අනුව 'වන්නම් 18' කට පමණක් නොව සත්ව, දේව හා රාජ ගුණ යන කාණ්ඩ තුනට බෙදා ඇත. මින් 'සත්ව වන්නමක්' නොවන්නේ කුමක්ද?", "අසදිස වන්නම", "ගජගා වන්නම", "මුසලඩි වන්නම", "උකුසා වන්නම", "අසදිස, ගණපති හා සුරපති යනු ආගමික හා දේව ගුණ වර්ණනා කරන වන්නම් වේ."),
        q("සෑම උඩරට වන්නමකම ආරම්භයේදී ශිල්පියා විසින් ගායනා කරන අර්ථ රහිත නාද මාලාව කුමක්ද?", "තානම", "කවිය", "කස්තිරම", "අඩව්ව", "උදාහරණ ලෙස 'තන තන තම් දන' ආදී වශයෙන් තානම ගයා තාලය ස්ථාපිත කෙරේ."),
        q("ගජගා වන්නමේ තානම හඳුන්වන සාම්ප්‍රදායික නාද පද පෙළ ආරම්භ වන්නේ කෙසේද?", "තන තම් දන තම් දන තනනා", "දොං ජිං ජිං තකට", "කිටි තක දොං ජිං", "තෙයි තත් තා තා", "ගජගා වන්නමේ මන්දගාමී හා ගාම්භීර රිද්මය එහි තානමෙන්ම පැහැදිලි වේ."),
        q("උඩරට වන්නම්වල ගැයෙන 'සුළු මැදුම් තාලය' හෙවත් මැදුම් දෙතිත අයත් වන්නේ කුමන මාත්‍රා ප්‍රමාණයකටද?", "මාත්‍රා දෙක හෝ තුන ආවර්තන රටාවට", "මාත්‍රා විස්සේ රටාවට", "මාත්‍රා තිස්දෙකේ රටාවට", "කිසිදු මාත්‍රාවක් නැති රටාවට", "දේශීය තාල ශාස්ත්‍රයේදී මැදුම් දෙතිත හා මහ දෙතිත වන්නම්වල බහුලව යෙදේ."),
        q("ගජගා වන්නම ගැයෙන හා නැටෙන ප්‍රධාන තාලය කුමක්ද?", "මැදුම් දෙතිත හෙවත් මැදුම් තනි තිත", "මහ තුන් තිත", "සුළු සිව් තිත", "අට මාත්‍රා තාලය", "ගජගා වන්නම මැදුම් දෙතිත අනුව ඇතාගේ ගාම්භීර ගමනින් ඉදිරිපත් කෙරේ."),
        q("තුරඟා වන්නම නැටීමේදී ශිල්පියා විසින් යොදාගන්නා විශේෂිත ගමන් විලාසය කුමක්ද?", "පැන පැන දුවන අසුගේ ඉදිරි පාද චලන අනුකරණය", "සෙමින් ඉදිරියට බඩගා යාම", "නිශ්චලව දණ ගසා සිටීම", "පසුපසට පමණක් ඇවිදීම", "අශ්වයෙකුගේ පිම්ම හා කර පැද්දීම තුරඟා වන්නමේ චලනවල අන්තර්ගත වේ."),
        q("උඩරට වන්නමක කොටස් පිළිවෙළින් සඳහන් කළහොත් නිවැරදි අනුපිළිවෙළ කුමක්ද?", "තානම, කවිය, කස්තිරම, සීරුමාරුව සහ අඩව්ව", "අඩව්ව, කවිය, තානම සහ කස්තිරම", "කස්තිරම, අඩව්ව, තානම සහ කවිය", "සීරුමාරුව, තානම, අඩව්ව සහ කවිය", "මන්දගාමීව ඇරඹී මධ්‍යම වේගයෙන් වර්ධනය වී අඩව්වෙන් කූටප්‍රාප්තියට පත් වේ."),
        q("වන්නමක 'කවිය' ගයමින් නටන විට නැට්ටුවා විසින් පෙන්විය යුතු ප්‍රධානම අභිනය කුමක්ද?", "කවියේ අර්ථය දෑත්, ඇස් හා සිරුරේ චලන මගින් නිරූපණය කිරීම", "වචන කිසිවක් නොකියා මුව වසාගෙන නිහඬව බලා සිටීම", "ප්‍රේක්ෂකාගාරයට පසුපස හැරී වේදිකාවෙන් ඉවත බැලීම", "ගායනය අවසන් වන තුරු ගැටබෙර වාදනය සම්පූර්ණයෙන් නැවැත්වීම", "වචනාර්ථය රසිකයාට දෘශ්‍යමාන කිරීම කවි නැටුම් කොටසේ අරමුණයි."),
        q("වන්නමක 'සීරුමාරුව' යනුවෙන් හඳුන්වනු ලබන කෙටි කොටස ඉටු කරන කාර්යය කුමක්ද?", "කස්තිරමෙන් පසු අඩව්ව නැටීම සඳහා නැට්ටුවා සූදානම් කර ලය සමබර කිරීම", "සම්පූර්ණ වන්නම් නැටුම අවසන් කර වේදිකාවෙන් පිටත් වීම සිදු කිරීම", "නැටුම මැද හිසේ පැළඳි වෙස් තට්ටුව හා ජටාව ගලවා තැන්පත් කිරීම", "රඟ මඩලට පැමිණෙන ප්‍රේක්ෂකයන්ට අසුන් පෙන්වා ආචාර සමාචාර කිරීම", "කස්තිරමේ වේගවත් බව අවසන් කර ඊළඟ අඩව්වට පිවිසීමට සීරුමාරුව පාලමක් වේ."),
        q("වන්නම් කවි රචනා කර ඇති සාම්ප්‍රදායික භාෂා ස්වරූපය කුමක්ද?", "මිශ්‍ර සිංහල, පාලි හා සංස්කෘත වචන මුසු වූ පැරණි කවි බස", "සරල ඉංග්‍රීසි ගද්‍ය භාෂාව", "නූතන ව්‍යවහාරික කෙටි පණිවිඩ බස", "විදේශීය ගද්‍ය නාට්‍ය භාෂාව", "මහනුවර යුගයේ උගත් කවීන්ගේ භාෂා ශෛලිය වන්නම් කවිවල කැපී පෙනේ."),
        q("උඩරට වන්නම්වල 'සමත්ත බව' හෙවත් ශාස්ත්‍රීය නීති පවත්වා ගැනීම සඳහා වන්නම අවසානයේ නටන අංගය කුමක්ද?", "අඩව්ව හා අවසාන තීර්මානය", "තානම", "සභා වන්දනාව", "බෙර අවදි කිරීම", "නැට්ටුවාගේ ඉහළම පාද හරඹ හා ජවය අවසාන අඩව්වෙන් ප්‍රකට වේ."),
        q("'දෙව්පුර ඇත් රජු මෙරගිර සේ...' යනුවෙන් ආරම්භ වන්නේ කුමන ප්‍රකට වන්නමේ කවියද?", "ගජගා වන්නමේ", "තුරඟා වන්නමේ", "උකුසා වන්නමේ", "මුසලඩි වන්නමේ", "සක්දෙවිඳුගේ ඇතු වන ඓරාවණයා පිළිබඳ වර්ණනාව මෙම කවියෙන් ඇරඹේ."),
        q("'සත් සිය සත් දෙන...' හෝ 'සුබ සිරි දෙන සුර...' යන කවිවලින් වර්ණනා කෙරෙන්නේ කුමන අංගයද?", "වන්නම් කවි සාහිත්‍යයේ දේව හා සත්ව ස්වභාවයන්", "කෘෂිකාර්මික බදු ක්‍රමය", "සන්නි රෝග නිවාරණය", "කෝලම් රජ චරිතය", "සෑම වන්නමකටම ආවේණික වූ වෘත්ත හා එළිසමය සහිත කවි පවතී."),
        q("මයුරා වන්නම ගැයෙන ප්‍රධාන තාලය කුමක්ද?", "මැදුම් තුන් තිත හෙවත් සුළු තුන් තිත", "මහ සතර තිත", "සුළු තනි තිත", "දොළොස් තිත", "මොනරාගේ ලාලිත්‍යමය ගමන හා පිල් විදහීම මැදුම් තුන් තිතට මනාව ගැළපේ."),
        q("සිංහරාජ වන්නමෙහි ප්‍රධාන වශයෙන් ඉස්මතු වන නව රසය කුමක්ද?", "වීර රසය සහ අද්භූත රසය", "කරුණා රසය පමණි", "හාස්‍ය රසය පමණි", "භීභත්ස රසය පමණි", "මෘග රාජයාගේ ප්‍රතාපවත් බව හා ශක්තිය වීර රසයෙන් ප්‍රකාශ වේ."),
        q("මුසලඩි වන්නමේදී හාවාගේ බිය හා අවට විපරම් කිරීම පෙන්වීමට නැට්ටුවා යොදාගන්නා මූලික චලනය කුමක්ද?", "දෙපසට කෙටි පැනුම් හා හිස හැරවීමේ චලන", "දිගු වේලාවක් නිශ්චලව වැතිරීම", "බිම පෙරළී සිනාසීම", "අහසට උස පිනුම් ගැසීම", "සංයමයෙන් යුත් කෙටි පිමි මගින් හාවාගේ ස්වභාවය අනුකරණය කරයි."),
        q("වන්නම් 18 අතර 'හනුමා වන්නම' නැටීමේදී වැඩි වශයෙන්ම ඉස්මතු කෙරෙන රසය කුමක්ද?", "හාස්‍ය රසය හා චපල චලන", "ශෝකී කරුණා රසය", "ගැඹුරු ශාන්ත රසය", "බියජනක රෞද්‍ර රසය", "වඳුරාගේ දඟකාර ගති හා මුහුණු අභිනය හාස්‍ය රසය ජනිත කරයි."),
        q("'සැවුලා' හෝ 'මොනරා' වැනි පක්ෂි චර්යා නොවන පක්ෂි වන්නම් දෙකක් මොනවාද?", "උකුසා වන්නම සහ කිරලා වන්නම", "ගජගා සහ තුරඟා වන්නම", "සිංහරාජ සහ මුසලඩි වන්නම", "උරඟා සහ හනුමා වන්නම", "උකුස්සාගේ පියාසැරියත් කිරලාගේ බිම් ඇවිදීමත් පක්ෂි වන්නම් දෙකකින් දැක්වේ."),
        q("උඩරට නර්තන විෂයේදී 'වන්නම් කවි' වල අවසන් පදයෙහි බොහෝ විට සඳහන් වන්නේ කුමක්ද?", "සත්වයාගේ හෝ දෙවියාගේ නමින් නම් කළ වන්නමේ නාමය", "ගැටබෙර වාදකයාගේ ගමේ නම", "වේදිකාවේ දිග හා පළල", "මුද්‍රණකරුගේ ලිපිනය", "උදාහරණ ලෙස '...කියමි ගජගා නම් වන්නමා' ලෙස වන්නම් නාමය කවිය අග යෙදේ."),
        q("දහඅට වන්නම් පැරණි රාජ සභාවේ ගැයූ ආකාරයෙන් පසු කාලීනව සිදු වූ ප්‍රධාන පරිවර්තනය කුමක්ද?", "ගායනයට පමණක් සීමා නොවී නැටුම් හා බෙර පද එක්ව ප්‍රාසාංගික වීම", "කවි සියල්ල මකා දැමීම", "නැටුමෙන් ඉවත් කර පොත්වල සැඟවීම", "බටහිර පියානෝ වාදනයට මාරු කිරීම", "කවිකාර මඩුවේ ගායන අංගයන්ට උඩරට සරඹ හා බෙර තාල එක් කර නර්තනයක් බවට පත් කෙරිණි."),
        q("'වන්නම් 18' හැරුණු විට උඩරට සම්ප්‍රදායේ නොපිළිගන්නා වන්නම කුමක්ද?", "කපිරිඤ්ඤා වන්නම", "වෛරෝඩි වන්නම", "නෛයඩි වන්නම", "සුරපති වන්නම", "සම්මත දහඅට වන්නම් නාමාවලියට කපිරිඤ්ඤා වන්නමක් අයත් නොවේ."),
        q("ගණපති වන්නම නැටීමේදී ශිල්පියා විසින් අභිනයෙන් නිරූපණය කරන්නේ කුමක්ද?", "ගජ මුහුණක් සහිත ගණ දෙවියන්ගේ රූපය හා ගුණ", "මුහුදු යාත්‍රාවක ගමන", "සිංහයෙකුගේ දඩයම", "අශ්ව රේස් තරගයක්", "මූසික වාහනය හා ගණ දෙවි ලක්ෂණ අත් මුද්‍රා මගින් නිරූපණය කරයි."),
        q("තුරඟා වන්නමේ කවිය සඳහා පාදක වූ ඓතිහාසික හා බෞද්ධ පුවත කුමක්ද?", "සිදුහත් බෝසතාණන් කන්ථක අසු පිට අභිනිෂ්ක්‍රමණය කිරීම", "විජය කුමරු ලංකාවට පැමිණීම", "දුටුගැමුණු රජුගේ කඩොල් ඇතු", "රාමායණයේ හනුමාන්", "කන්ථක අසුගේ වේගවත් හා ගෞරවනීය ගමන තුරඟා වන්නමේ කවියේ වර්ණනා කෙරේ."),
        q("අසදිස වන්නමේ කවි තුළින් වර්ණනා කෙරෙන ප්‍රධානතම චරිතය කවුද?", "සම්මා සම්බුදුරජාණන් වහන්සේ", "මලය රජතුමා", "සක්‍ර දේවේන්ද්‍රයා", "විෂ්ණු දෙවියන්", "බුදුරදුන්ගේ තිලෝගුරු ගුණ හා ප්‍රාතිහාර්යයන් අසදිස වන්නමෙන් ගැයේ."),
        q("වන්නම් නැටුමකදී 'මාත්‍රා 3' බැගින් යෙදෙන තුන් තිත තාලයෙන් ගැයෙන ප්‍රසිද්ධ වන්නම් යුගලයකට උදාහරණයක් කුමක්ද?", "මයුරා වන්නම සහ හනුමා වන්නම", "ගජගා සහ උදාර වන්නම", "තුරඟා සහ සිංහරාජ වන්නම", "නෛයඩි සහ උරඟා වන්නම", "මැදුම් හෝ සුළු තුන් තිත මත පදනම් වූ වන්නම් කිහිපයක් 18 වන්නම් අතර පවතී."),
        q("උඩරට වන්නම්වලදී 'මහ දෙතිත' හෙවත් මාත්‍රා හතර බැගින් ගැයෙන විශාල කාල පරාසයක් ඇති වන්නමක් කුමක්ද?", "අසදිස වන්නම හෝ සිංහරාජ වන්නම", "මුසලඩි වන්නම", "කිරලා වන්නම", "තුරඟා වන්නම", "දිගු මාත්‍රා රටාවන් සහිත ගාම්භීර වන්නම් මහ තාලවලින් ගැයේ."),
        q("වන්නමක 'කස්තිරම' වාදනය කරන විට ගැටබෙර වාදකයාගේ කාර්යභාරය කුමක්ද?", "ප්‍රබල හා වේගවත් බෙර පද මාලාවක් වාදනය කර තීර්මානයකින් නැවතීම", "බෙරය දෑතින් වසාගෙන කිසිදු නාදයක් නොදී නිහඬව සිටීම", "පද වාදනය නොකර වන්නම් කවිය පමණක් ගායනා කිරීම", "ගැටබෙරය පසෙකින් තබා තාලම්පට පමණක් අතින් ගෙන වැයීම", "කස්තිරමේ ජවය හා ප්‍රබෝධය රඳා පවතින්නේ ගැටබෙර පදවල තියුණු බව මතය."),
        q("උඩරට දහඅට වන්නම් පුහුණුවීමේදී ශිෂ්‍යයා 'මුලින්ම' ඉගෙන ගන්නා පහසුම හා ආරම්භක වන්නම බොහෝ විට කුමක්ද?", "ගජගා වන්නම හෝ තුරඟා වන්නම", "අසදිස වන්නම", "වෛරෝඩි වන්නම", "කුදිරඩි වන්නම", "පැහැදිලි මන්දගාමී රිද්මය හා ප්‍රසන්න චලන නිසා ගජගා වන්නම මූලිකව උගන්වයි."),
        q("නෛයඩි වන්නමේ තේමාව ලෙස සත්ව චර්යාවට අමතරව ඇතුළත් වන බෝසත් සිරිත් පුවත කුමක්ද?", "සිදුහත් කුමරු ධනු ශිල්පය ප්‍රදර්ශනය කිරීම හෝ නාග රාජ වර්ණනාව", "අනුරාධපුර සිව් මහා දේවාල ඉදිකිරීම හා පූජා විධි", "විජය කුමරු හා කුවේණිගේ ශාපය පිළිබඳ පුවත", "විශාල මහා සමුද්‍රය නැව් මගින් තරණය කිරීමේ පුවත", "විවිධ ගුරුකුල අනුව නෛයඩි වන්නමේ කවි අර්ථ කථන පවතී."),
        q("උරඟා වන්නමේදී නාගයාගේ හිස එසවීම හා බිම දිගේ ලිස්සා යාම පෙන්වීමට නැට්ටුවා භාවිත කරන ශාරීරික උපක්‍රමය කුමක්ද?", "බෙල්ලේ හා ඉණෙහි සියුම් වක්‍ර චලන සහ පතක අත් චලන", "දණහිස් බිම දිගේ ඇදගෙන යාම", "හිස බිම ගසමින් සිටීම", "දෙඅත් මිට මොළවා සිටීම", "සුමට හා තරංගාකාර චලන උරඟා වන්නමේ අනන්‍යතාවයි."),
        q("කිරලා වන්නමේදී පක්ෂියා කෑගසමින් අහසට නැඟී නැවත බිම වැසීම දැක්වීමට යොදාගන්නා නැටුම් පියවර කුමක්ද?", "සැහැල්ලු පැනුම් සහ දෑත් පියාපත් මෙන් දෙපසට සැලීම", "බර අඩි තබමින් නතර වීම", "කරකැවිල්ලකින් බිම හිඳගැනීම", "වේදිකාවේ පසෙකින් හිටගෙන සිටීම", "පක්ෂියාගේ සැහැල්ලු ශරීර ස්වභාවය කඩිසර චලනවලින් නිරූපණය කෙරේ."),
        q("උඩරට වන්නමක 'තාල රූපය' වෙනස් වුවහොත් වන්නමේ කුමන අංගයට එය සෘජුවම බලපායිද?", "නර්තන පියවරවල වේගය හා ගායනයේ මාත්‍රා රටාවට", "වෙස් තට්ටුවේ බර ප්‍රමාණයට", "සිළම්බුවල ලෝහ වර්ගයට", "වේදිකා තිරයේ වර්ණයට", "තාලය යනු වන්නමේ කාල රාමුව බැවින් ගැයුම්, වැයුම් හා නැටුම් සියල්ල ඒ අනුව හැඩගැසේ."),
        q("උඩරට වන්නම්වලදී 'මාත්‍රා 16' ක් හෝ 'මාත්‍රා 8' ක් ආවර්තනය වන තාල ක්‍රමය හඳුන්වන සිංහල නාමය කුමක්ද?", "සතර තිත හෙවත් සිව් තිත තාලය", "තනි තිත", "අර්ධ තිත", "ශුන්‍ය තිත", "මාත්‍රා ප්‍රමාණය අනුව තනි තිත, දෙතිත, තුන් තිත හා සිව් තිත ලෙස බෙදා දැක්වේ."),
        q("උඩරට වන්නම් සමූහ නර්තනයක් ලෙස ඉදිරිපත් කිරීමේදී අත්‍යවශ්‍ය වන ප්‍රධානතම ගුණාංගය කුමක්ද?", "තානමේ සිට අඩව්ව දක්වා සියලු දෙනා එකම ඉරියව්වකින් හා තාලයකින් යාම", "සෑම නැට්ටුවෙකුම තමා කැමති වෙනස් වන්නම් පද වෙන වෙනම නැටීම", "මූලික කස්තිරම සම්පූර්ණයෙන් මඟ හැර කෙළින්ම අවසන් අඩව්වට යාම", "කණ්ඩායමේ අනෙක් අය නටද්දී තමන් කැමති වේලාවක නැටුමෙන් නතර වීම", "ඒකාබද්ධ රිද්මය හා සමගාමී චලන සමූහ වන්නම් නර්තනය අලංකාර කරයි."),
        q("වන්නම් කවියේ 'විරිත' යනුවෙන් හඳුන්වන්නේ කුමක්ද?", "කවි පදයක ඇති අක්ෂර හා මාත්‍රා ගැළපීමේ රිද්ම සැකිල්ල", "වේදිකාවේ මුළු විශාලත්වය", "ගැටබෙරයේ දිග ප්‍රමාණය", "වෙස් ඇඳුමේ මිල", "කවියේ විරිත හා තාලය එකට බැඳී පවතින බැවින් ගායනය මිහිරි වේ."),
        q("උඩරට නැටුමේදී 'මුල් තානම' ගැයීමෙන් පසු නැට්ටුවා 'අතින් තාල අල්ලමින්' හෝ 'මණ්ඩිය පැද්දෙමින්' කරන්නේ කුමක්ද?", "තාලය හා රිද්මය ශරීරයට ආරෝපණය කර ගැනීම", "ප්‍රේක්ෂකයන්ට පිටව යාමට සංඥා කිරීම", "වෙස් තට්ටුව ගැලවීම", "බෙර වාදනය නතර කිරීම", "තානම නැටීම මගින් ප්‍රේක්ෂකයාගේ අවධානය අදාළ තේමාව වෙත යොමු කරයි."),
        q("සම්ප්‍රදායික දහඅට වන්නම් නාමාවලියෙහි 'සුරපති' වන්නම හැරුණු විට දෙවිවරුන් පිළිබඳව ගැයෙන තවත් වන්නමක් කුමක්ද?", "ගණපති වන්නම", "තුරඟා වන්නම", "මුසලඩි වන්නම", "කිරලා වන්නම", "ගණපති, සුරපති හා වෛරෝඩි වන්නම් දේව ස්තෝත්‍ර හා පුරාවෘත්ත ඇසුරෙන් නිර්මාණය වී ඇත."),
        q("උඩරට නැටුමේදී වන්නම් කවියක් ගායනා කිරීමට පෙර බෙරකරු විසින් වාදනය කරන පූර්ව පද කොටස කුමක්ද?", "වට්ටම හෙවත් තානම් පදය", "අවසන් තීර්මානය", "දිය කැපීමේ පදය", "කෝලම් හේවා පදය", "නැට්ටුවාට හා ගායකයාට ලය හඳුන්වා දීමට වට්ටම් පදය වාදනය කෙරේ."),
        q("'සවනත මිහිරි වන...' ආදී ලෙස ශාස්ත්‍රීය කාව්‍ය ගුණයෙන් පිරි වන්නම් කවිවලින් පෙන්නුම් කරන අමතර කලා කුසලතාව කුමක්ද?", "කාව්‍ය රචනා ශිල්පය හා ඡන්දස් අලංකාර දැනුම", "පහතරට කෝලම් කැටයම් ශිල්ප දැනුම", "වේදිකා ආලෝක සැලසුම් තාක්ෂණ දැනුම", "බටහිර සම්භාව්‍ය බැලේ න්‍යාය දැනුම", "මහනුවර යුගයේ සාහිත්‍ය හා සංගීත කලාව අතර තිබූ සමීප බැඳීම මෙයින් පැහැදිලි වේ."),
        q("උඩරට දහඅට වන්නම්වල 'අවසන් කොටස' ලෙස නටන අඩව්ව හඳුන්වන විශේෂ ලක්ෂණය කුමක්ද?", "වේගවත් පිනුම්, කැරකිලි සහ සංකීර්ණ තාල රටා තුළින් ශිල්පීය හැකියාව පෙන්වීම", "සෙමින් හිඳගෙන භාවනා කිරීමේ නිශ්චල ඉරියව්ව දැක්වීම", "දෙඅත් නොසොල්වා මන්දගාමීව වේදිකාව වටා ඇවිදීම", "පළමු කවිය නැවත මුල සිට ගද්‍ය ආකාරයෙන් කියවීම", "සම්පූර්ණ වන්නමේ උච්චතම අවස්ථාව අඩව්වෙන් සනිටුහන් වේ."),
        q("උඩරට වන්නම් ගායනයේදී 'නාද මාධූර්යය' රැකගැනීම සඳහා ගායකයා සතුව තිබිය යුතු මූලික කුසලතාව කුමක්ද?", "නිවැරදි ස්වර ස්ථාන, පැහැදිලි උච්චාරණය හා ලය පාලනය", "හැකිතාක් උස් හඬින් කෑගැසීම", "වචන කපා හැරීම", "තාලයෙන් පිටතට ගායනා කිරීම", "තානම හා කවියේ රසය දැනෙන්නේ පැහැදිලි හා මිහිරි ගායනයෙනි."),
        q("ගජගා වන්නමේදී ඇතාගේ කන් සැලීම හා සොඬය එසවීම දැක්වීම සඳහා යොදන මූලික ඉරියව්ව කුමක්ද?", "මණ්ඩි ඉරියව්වෙන් සිට දෑත් හා උරහිස් ලලිත ලෙස පැද්දීම", "කෙළින් සිටගෙන දෑත් පහත හෙළීම", "බිම දිගා වී හිස එසවීම", "පසුපස හැරී අත්පුඩි ගැසීම", "දළ ඇතාගේ ගාම්භීර අංග චලන මණ්ඩි ඉරියව්ව තුළින් ප්‍රකට කෙරේ."),
        q("තුරඟා වන්නම නැටීමේදී 'කන්ථක අසු' ගඟෙන් එතෙර වීම නිරූපණය කරන්නේ කුමන චලනයෙන්ද?", "ඉහළට නැඟ ඉදිරියට පැනීමේ මාත්‍රා රටාවකින්", "බිම හිඳගෙන අත් සැලීමෙන්", "පසුපසට සෙමින් ගමන් කිරීමෙන්", "නිශ්චලව සිටගෙන සිටීමෙන්", "අනෝමා නදිය තරණය කරන වික්‍රමය ජවසම්පන්න පැනුම් මගින් නිරූපණය වේ."),
        q("මයුරා වන්නමේ කවිය ගයන විට ගායනය සමඟ නැට්ටුවා පවත්වා ගත යුතු ප්‍රධාන දෘෂ්ටිය කුමක්ද?", "ප්‍රසන්න හා ආඩම්බර බැල්මකින් ඉහළ හා දෙපස බැලීම", "බියෙන් බිම බලා ගැනීම", "දෑස් වසාගෙන සිටීම", "කෝපයෙන් රවා බැලීම", "මොනරාගේ උදාර පෙනුම හා සුන්දරත්වය ප්‍රසන්න දෘෂ්ටියෙන් පෙන්වයි."),
        q("උකුසා වන්නමේදී උකුස්සා ගොදුරක් රැගෙන ඉහළ අහසට නැඟෙන අවස්ථාවේ බෙර වාදනය සිදුවන්නේ කෙසේද?", "මධ්‍ය ලයේ සිට ක්‍රමයෙන් වේගවත් ද්‍රුත ලයට පිවිසීමෙන්", "සම්පූර්ණයෙන් බෙරය නිහඬ කිරීමෙන්", "විලම්බ ලයට පමණක් වැයීමෙන්", "තාලම්පට පමණක් ගැසීමෙන්", "ගොදුර ඩැහැගැනීමේ ජවය වේගවත් බෙර පදවලින් තීව්‍ර වේ."),
        q("හනුමා වන්නමේදී වඳුරෙකු පලතුරු කෑම සහ වටපිට බැලීම දැක්වීම සඳහා යොදාගන්නා අංගය කුමක්ද?", "මුහුණු අභිනය හා කඩිසර හස්ත චලන", "දිගු පිනුම් පමණක් ගැසීම", "බිම හිඳ ගීත ලිවීම", "හිස නොසොල්වා සිටීම", "හනුමා වන්නමේ සජීවී හාස්‍යය මුහුණු අභිනයෙන් හා ක්ෂණික හැරීම්වලින් ඉස්මතු වේ."),
        q("සිංහරාජ වන්නමේ කවි පද තුළ සිංහයා වාසය කරන ස්ථානය ලෙස බොහෝ විට වර්ණනා කෙරෙන්නේ කුමක්ද?", "රන් ගල් ගුහාව හෙවත් කේසර සිංහ විමානය", "මුහුදු පතුල", "වැව් ඉවුර", "ගම්මාන මැද පිටිය", "ගිරි ලෙනක සිට පිටතට එන කේසර සිංහයා කවිවලින් අලංකාරව වර්ණනා වේ."),
        q("මුසලඩි වන්නම නැටීමේදී ශිල්පියා පෙන්නුම් කරන 'මුසල පිම්ම' යනු කුමක්ද?", "දෙපා එකට තබා මණ්ඩි ඉරියව්වෙන් ඉදිරියට හා පැත්තට පැනීම", "තනි කකුලෙන් උඩ බලා සිටීම", "බිම වැතිරී පෙරළීම", "හිස බිම තබා සිටීම", "හාවෙකු තණ බිමේ පනින කඩිසර ගමන මෙම විශේෂ පියවරෙන් දැක්වේ."),
        q("කිරලා වන්නමේ කවිය අනුව කිරලා පක්ෂියා බිත්තර රකින්නේ හා හැසිරෙන්නේ කුමන පරිසරයකද?", "වෙල් ඉපනැල්ලේ හා ගොඩ බිම් පිටියේ", "මහා සාගරයේ ගැඹුරේ", "හිම කඳු මුදුනේ", "උස් ගස් බෙන තුළ", "පොළොව මත කූඩු තනා හඬ නඟන කිරලාගේ ස්වභාවය වන්නමේ ගැයේ."),
        q("නෛයඩි වන්නමේදී සිදුහත් කුමරුන් ශිල්ප දැක්වූ දුන්න හැඳින්වෙන සාම්ප්‍රදායික නාමය කුමක්ද?", "සහස්‍ර ථාම දුන්න", "විජය දුන්න", "ගාණ්ඩීව දුන්න", "පිනාක දුන්න", "බෝසතුන් දහසක් දෙනාට එසවිය නොහැකි දුන්න එසවූ පුවත වන්නම් කවියේ එයි."),
        q("උරඟා වන්නමේ තානම ගැයීමේදී හඬ උස් පහත් කරන ආකාරයෙන් නිරූපණය වන්නේ කුමක්ද?", "සර්පයෙකුගේ වක්‍ර හා සුමට ගමන් රටාව", "ඇතාගේ බර කුංචනාදය", "අශ්වයාගේ හේෂාරවය", "සිංහයාගේ ගර්ජනාව", "තානමේ ස්වර ගමන පවා සර්ප චලනයේ ලාලිත්‍යය සිහිගන්වයි."),
        q("සුරපති වන්නමේදී දැක්වෙන මල් හී සැර විදීමේ පුවත සම්බන්ධ වන්නේ කුමන දේව චරිතයකටද?", "අනංගයා හෙවත් මල්සරා සහ ඊශ්වර දෙවියන්", "ගණ දෙවියන්", "සමන් දෙවියන්", "කතරගම දෙවියන්", "උමා දේවිය නැති වූ ශිවගේ කතා පුවත සුරපති වන්නමේ ජනප්‍රිය අර්ථයයි."),
        q("ගණපති වන්නමේදී ගණ දෙවියන්ගේ වාහනය ලෙස කවිවලින් වර්ණනා කෙරෙන සත්වයා කවුද?", "මූසිකයා හෙවත් මීයා", "මොනරා", "ගුරුළා", "සිංහයා", "මූසික වාහනාරූඪ ගණපති දෙවිඳුන්ගේ ස්වරූපය වන්නම් කවියේ වර්ණනා කෙරේ."),
        q("උදාර වන්නම නැටීමේදී නැට්ටුවා 'සිව්රඟ සෙනඟ' නිරූපණය කරන්නේ කෙසේද?", "ඇත්, අස්, රිය, පාබල යන සේනාංක හතර අභිනයෙන් දැක්වීමෙන්", "තනිවම බිම ඉඳගෙන සිටීමෙන්", "කඩු දෙකක් බිම තැබීමෙන්", "රබන් ගැසීමෙන්", "රජුගේ රාජකීය පෙරහැරේ සියලු සේනාංක හස්ත මුද්‍රා හා පාද චලනවලින් පෙන්වයි."),
        q("අසදිස වන්නමේ එන 'සසර දුකින් එතෙර කරන...' වැනි පද තුළින් පිළිබිඹු වන සාහිත්‍යමය ගුණය කුමක්ද?", "සම්බුදු ගුණ වන්දනාව හා ගැඹුරු ධර්ම භක්තිය", "රණකාමී යුද උද්‍යෝගය", "ගැමි කෘෂි ශ්‍රමය", "සත්ව දඩයම", "සෙසු වන්නම්වලට වඩා ඉහළ ධාර්මික ශාන්ත රසයක් අසදිස වන්නමේ ඇත."),
        q("වෛරෝඩි වන්නමේදී දිව්‍ය අංගනාවන් හා සුර ලොව වර්ණනා කිරීමට යොදාගන්නා නැටුම් ශෛලිය කෙබඳුද?", "මෘදු ලාලිත්‍යමය හා පිරිපුන් මණ්ඩි චලන", "රෞද්‍ර පොරබැදීම්", "අක්‍රමවත් දිවීම්", "බිම ඇදගෙන යාම්", "සෞම්‍ය හා අද්භූත රසය රැකෙන සේ සියුම් අත් මාරු මෙහිදී භාවිත කෙරේ."),
        q("ඊරඩි වන්නමේදී යුද බිමේ අසරුවෙකු හෝ සෙබළෙකුගේ 'ආවේගශීලී පියවර' පෙන්වීමට ගන්නා තාලය කුමක්ද?", "සුළු තනි තිත හෝ වේගවත් සිව් මාත්‍රා තාලය", "අතිශය මන්ද විලම්බ තාලය", "තාල රහිත නිහඬතාව", "හින්දුස්ථානි තීන්තාලය", "රණශූර ජවය ඉස්මතු කිරීමට කෙටි හා තියුණු මාත්‍රා රටා යොදා ගනී."),
        q("උඩරට දහඅට වන්නම්වල 'තාලම්පට' නාද කරන විට එක් 'තිතක්' ලෙස සැලකෙන්නේ කුමක්ද?", "තාලම්පට පියන් දෙක වසා ගසන අවධාරණාත්මක ශබ්ද ස්ථානය", "බෙර වරපට ගැටගැසීම", "කවියේ අවසාන වචනය", "නැට්ටුවා හිඳගන්නා මොහොත", "තිත මගින් තාලයේ බර වැටෙන නිශ්චිත මාත්‍රාව සියලු දෙනාට දැනුම් දේ."),
        q("උඩරට වන්නම්වල 'මහ දෙතිත' හා 'මැදුම් දෙතිත' අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "මහ දෙතිතේ මාත්‍රා කාලය දිගු හා ගාම්භීර වන අතර මැදුම් දෙතිත මධ්‍යම වේගයෙන් යුක්ත වීම", "මහ දෙතිත ගයන විට කිසිසේත්ම තාලම්පට හා බෙර වාදනය නොකිරීම", "මැදුම් දෙතිත දේශීය නොවී බටහිර සම්භාව්‍ය සංගීතයට පමණක් අයත් වීම", "මහ දෙතිත හා මැදුම් දෙතිත යන දෙකම කිසිදු වෙනසකින් තොරව එකම වේගයෙන් වැයීම", "මාත්‍රා පරතරය අනුව සුළු, මැදුම් හා මහ යනුවෙන් තාල ලය බෙදා දැක්වේ."),
        q("වන්නමක 'කවිය' සහ 'කස්තිරම' අතර කෙටි සම්බන්ධීකරණය ඇති කරන 'හමාර කවිය' කුමක් සඳහා වැදගත්ද?", "ගායනයේ සිට වේගවත් නෘත්ත කස්තිරම වෙත සුමටව මාරු වීමට", "ප්‍රසංගය මැදින් නැවැත්වීමට", "වෙස් ඇඳුම ගැලවීමට", "වෙනත් වන්නමකට පැනීමට", "කවිය අවසන් වන ස්ථානයේදී බෙරකරු හා නැට්ටුවා එකඟව කස්තිරම අරඹයි."),
        q("උඩරට වන්නමක කවි කිහිපයක් ඇති විට සෑම කවියක් අවසානයේම අඩව්ව නටනවාද?", "නැත, සාමාන්‍යයෙන් එක් එක් කවිය අවසානයේ කස්තිරම් නටා අවසාන කවියෙන් පසු ප්‍රධාන අඩව්ව නටයි", "ඔව්, වන්නම් කවියේ පදයෙන් පදයට අඩව් හා පිනුම් ගසමින් රංගනය ඉදිරිපත් කරයි", "උඩරට වන්නම් සම්ප්‍රදාය තුළ අවසන් කවියෙන් පසුව පවා අඩව් කිසිසේත්ම නොනටයි", "සියලුම වන්නම් කවි ගැයීමෙන් පසු නැට්ටුවන් වේදිකාව මත හිඳගෙන අභිනය දක්වයි", "සාම්ප්‍රදායික වන්නම් පෙළගැස්ම අනුව ප්‍රධාන කූටප්‍රාප්තිය අවසානයේ පිහිටයි."),
        q("දහඅට වන්නම් රචනා වූ මහනුවර රාජධානි සමයේ රජුගේ විනෝදාස්වාදය හා ශාස්ත්‍රීය සභාව හැඳින්වූයේ කෙසේද?", "කවිකාර මඩුව", "සන්නි මඩුව", "දෙවොල් මඩුව", "ගම්මඩුව", "ශ්‍රී වීර පරාක්‍රම නරේන්ද්‍රසිංහ රජුගේ කවිකාර මඩුවේදී වන්නම් කවි ගායනය ප්‍රචලිත විය."),
        q("වන්නම් කවි රචනා කිරීමේදී මහනුවර යුගයේ උගත් භික්ෂූන් වහන්සේලා හා කවීන් කළ දායකත්වය කුමක්ද?", "සත්ව හා දේව චර්යා සාහිත්‍යමය හා බෞද්ධ පසුබිමකින් කවි බවට පත් කිරීම", "මඟුල් බෙර හා යක් බෙර කඳන් නිපදවීම", "පහතරට සන්නි වෙස්මුහුණු පින්තාරු කිරීම", "කෝලම් රංග පිටපත් රචනා කර ඉදිරිපත් කිරීම", "මල්වතු පාර්ශ්වයේ හා රාජ සභාවේ පඬිවරුන්ගේ සාහිත්‍ය ශක්තිය වන්නම් තුළ දක්නට ලැබේ."),
        q("උඩරට නැටුමේ 'පන්තේරු' රංගනය සමඟ වන්නම් නැටීමේදී නැට්ටුවන් අතර තිබිය යුතු විශේෂ කුසලතාව කුමක්ද?", "තාලයට පන්තේරු කරකවමින් වන්නම් පද සමඟ ඒකාබද්ධ කිරීම", "පන්තේරු බිම දමා පෑගීම", "තනිවම කෑගැසීම", "ගැටබෙරය පයින් ගැසීම", "උපකරණ සහිත වන්නම් නැටුම්වලදී උපකරණයේ රිද්මයද නැටුමට එක් වේ."),
        q("උඩරට වන්නම් අතුරින් 'සමනල වන්නම' හෝ 'මහාබෝ වන්නම' වැනි අමතර වන්නම් හඳුන්වනු ලබන්නේ කුමන නමකින්ද?", "දහඅට වන්නම් පරිබාහිර හෙවත් නූතන අතිරේක වන්නම්", "පහතරට ශාන්තිකර්මවල එන දහඅට සන්නි අංග", "සබරගමු සම්ප්‍රදායේ පැරණි කෝලම් නැටුම්", "දකුණු ඉන්දීය භරත නාට්‍යම් පදම් හා වර්ණම්", "සාම්ප්‍රදායික 18 න් පසුව බිහිවූ වන්නම් පාසල් හා වේදිකා රංගනයේදී යොදා ගැනේ."),
        q("වන්නමක 'මාත්‍රා 7' බැගින් යෙදෙන විෂම තාල රටාවක් දක්නට ලැබෙන්නේ නම් එය හඳුන්වන දේශීය තාල නාමය කුමක්ද?", "සුළු තුන් තිත (2+2+3) හෝ සප්ත මාත්‍රා රටාව", "මාත්‍රා හතර බැගින් වූ සම සිව් තිත රටාව", "මාත්‍රා දෙක බැගින් වූ සරල මැදුම් දෙතිත", "මාත්‍රා දහසයකින් යුත් චතුර් මාත්‍රා ආවර්තය", "3+4 හෝ 2+2+3 ලෙස බෙදෙන සත් මාත්‍රා තාල සමහර වන්නම්වල සුන්දරත්වය වැඩි කරයි."),
        q("ගජගා වන්නමේ 'කස්තිරම' නටන අවස්ථාවේදී නැට්ටුවාගේ ශරීරය පිහිටන ආකාරය කෙබඳුද?", "පුළුල් මණ්ඩි ඉරියව්වෙන් බර තබා දෙපසට ශක්තිමත්ව හැරෙමින්", "එක් පාදයක ඇඟිල්ලකින් පමණක් සමතුලිතව හිටගෙන", "වේදිකාවේ මුල්ලක නිහඬව හිඳගෙන අත් බැඳගෙන", "සෘජුව ගල් ගැසී කිසිදු චලනයක් නොදක්වා", "ඇතෙකුගේ මහිමය කස්තිරමේ සෑම අඩියකින්ම විදහා පෙන්වයි."),
        q("වන්නමක 'තානම' ගැයීමේදී වර්තමාන වේදිකාවේ සමූහ ගායනය යොදා ගන්නේ ඇයි?", "ප්‍රබල හා ඒකාබද්ධ නාද ගුණයක් ප්‍රේක්ෂකයාට ලබා දීමට", "එක් අයෙකුට වචන අමතක වන නිසා", "ගැටබෙරය නොමැති නිසා", "කාලය කෙටි කිරීමට", "නැට්ටුවන් කණ්ඩායමම එක් හඬින් තානම ගයන විට ගාම්භීර වේදිකා පරිසරයක් මැවේ."),
        q("උඩරට නැට්ටුවෙකු 'සිංහරාජ වන්නම' නැටීමේදී පළඳින වෙස් ඇඳුමේ 'හිසේ සිළුමිණ' හා 'තට්ටුව' රැකගත යුත්තේ කෙසේද?", "වේගවත් හිස චලනවලදී පවා සමතුලිතව හා ගෞරවයෙන් රඳවා ගනිමින්", "හිස් වැස්ම අතින් අල්ලාගෙන", "වෙස් තට්ටුව ගලවා බිම තබා", "හිස පහතටම හරවාගෙන", "හිස් පැළඳුම අලංකාරව රඳවා නැටීම නැට්ටුවාගේ පරිණත පුහුණුව පෙන්වයි."),
        q("තුරඟා වන්නමේ කවිය අවසානයේ නටනු ලබන අඩව්ව තුළ බහුලව දැකිය හැකි පාද ක්‍රියාව කුමක්ද?", "පොළොවෙන් ඉහළට පනින වේගවත් කරකැවිලි හා පසුපස කකුල් එසවීම්", "දෙදණහිස් බිම තබා වන්දනා ඉරියව්වෙන් සිටීම", "එකම තැන නිශ්චලව සිටගෙන හිස වැනීම", "සෙමින් මන්දගාමීව වේදිකාවේ ඉදිරියට ඇවිදීම", "අශ්වයෙකුගේ වේගවත් ජවය අඩව්වේදී උපරිමයෙන් ඉස්මතු වේ."),
        q("මුසලඩි වන්නමේ 'හාවා' ගැන කියැවෙන කවියේදී නැට්ටුවා 'කන් දෙක' නිරූපණය කරන්නේ කෙසේද?", "දබරැඟිලි හා මැදැඟිලි කන් දෙපස ඉහළට දිගු කර සෙලවීමෙන්", "පාද දෙක ඉහළට එසවීමෙන්", "මුහුණ රෙදි කඩකින් වැසීමෙන්", "බෙල්ල කඩා හෙළීමෙන්", "සියුම් අංග අභිනයෙන් සත්ව ලක්ෂණ දැක්වීම ප්‍රේක්ෂකයාට ඉතා රසවත්ය."),
        q("උඩරට වන්නම්වල 'බෙර පද' කියවන විට ගැටබෙරයේ වම් ඇසින් හා දකුණු ඇසින් නැඟෙන ප්‍රධාන හඬවල් යුගලය කුමක්ද?", "වම් ඇසින් ගැඹුරු 'දොං' හඬත් දකුණු ඇසින් තියුණු 'තත්/කිට' හඬත්", "දෙපැත්තෙන්ම එකම සීනු නාදයක් හා උස් හඬක්", "දෙපැත්තෙන්ම හොරණෑවට සමාන නළා හඬක්", "දෙපැත්තෙන්ම කිසිදු නාදයක් නොමැති නිහඬතාව", "දෙඅතින් වයන නාදවල විවිධත්වය වන්නම් කස්තිරම් අලංකාර කරයි."),
        q("ගණපති වන්නම නැටීමේදී නැට්ටුවා 'වැඳ නමස්කාර කරන' මුද්‍රාව බහුලව යොදන්නේ ඇයි?", "ගණ දෙවියන්ට ඇති පූජනීය භක්තිය හා ආශිර්වාදය ප්‍රකාශ කිරීමට", "වෙහෙස දැනුණු නිසා", "කාලය පිරවීමට", "ප්‍රේක්ෂකයන්ගෙන් මුදල් ඉල්ලීමට", "පූජා හා ස්තෝත්‍ර වන්නමක් වන බැවින් භක්ති රසය ප්‍රධාන වේ."),
        q("වන්නමක් ඉගෙනීමේදී 'තානම හඬ නඟා ගැයීම' නැටුම් ශිෂ්‍යයාට උපකාරී වන්නේ කෙසේද?", "නැටුමේ රිද්මය, හුස්ම පාලනය සහ ආත්ම විශ්වාසය එක්ව ගොඩනැඟීමට", "ගායන කටහඬ දුර්වල වී නැති කර ගැනීමට", "වන්නමේ මූලික තාල රටාව අමතක කර දැමීමට", "නැටුම අතරමග නතර කර වේදිකාවෙන් පිටවීමට", "ගායනය හා නර්තනය එකවර කිරීම උඩරට නර්තන ශිල්පියාගේ සුවිශේෂී කුසලතාවකි."),
        q("උඩරට දහඅට වන්නම් සම්ප්‍රදායේ 'විභාග' හෝ 'ප්‍රසංග' අවස්ථාවලදී වන්නමක් ඇගයීමට ලක් කරන ප්‍රධාන නිර්ණායක මොනවාද?", "ගායන මාධූර්යය, තාල නිවැරදි බව, අංග චලන හා අභිනය", "ඇඳුමේ මිල පමණි", "ශිල්පියාගේ උස පමණි", "බෙරයේ බර පමණි", "ගැයුම, වැයුම හා රැඟුම යන ත්‍රිවිධාංගයම සමබර විය යුතුය."),
        q("උඩරට දහඅට වන්නම් අද වන විට ලෝක සංස්කෘතික උරුමයක් සේ අගය කරන්නේ කුමන හේතුව නිසාද?", "සාහිත්‍යය, සංගීතය, තාල ශාස්ත්‍රය හා නර්තන කලාව එක්ව බැඳුණු අද්විතීය කලා සම්ප්‍රදායක් බැවින්", "එය ඉතා කෙටි ජනප්‍රිය සැහැල්ලු ගීත කිහිපයක් පමණක් වන බැවින්", "එය විදේශීය නාට්‍ය අංගයක් අනුකරණය කර සෑදූ නිසා බැවින්", "එය හුදු කායික ක්‍රීඩා අභ්‍යාස මාලාවක් පමණක් වන බැවින්", "සිංහල සංස්කෘතික ප්‍රතිභාවේ උච්චතම ප්‍රකාශනයක් ලෙස 18 වන්නම් සදාකාලිකව අගය කෙරේ.")
    )
}
